from itertools import product

def solve(inp):
    R,C=len(inp),len(inp[0])
    cells=[(r,c) for r in range(R) for c in range(C) if inp[r][c]==8]
    cellset=set(cells)
    # pieces: O squares and L triominoes (2x2 minus a corner), fully within cellset
    pieces=[]
    for r in range(R-1):
        for c in range(C-1):
            blk=[(r+i,c+j) for i in range(2) for j in range(2)]
            if all(p in cellset for p in blk):
                pieces.append((tuple(blk),1))
            for mi,mj in product((0,1),(0,1)):
                L=[(r+i,c+j) for i in range(2) for j in range(2) if (i,j)!=(mi,mj)]
                if all(p in cellset for p in L):
                    missing=(mi,mj)
                    col={(0,0):2,(1,0):3,(0,1):4,(1,1):5}[missing]
                    pieces.append((tuple(L),col))
    # exact cover search
    sols=[]
    def bt(rem, chosen):
        if not rem:
            sols.append(list(chosen)); return
        if len(sols)>3: return
        first=min(rem)
        for pcs,col in pieces:
            if first in pcs and set(pcs)<=rem:
                bt(rem-set(pcs), chosen+[(pcs,col)])
    bt(frozenset(cells),[])
    return sols

def render(inp, sol):
    out=[row[:] for row in inp]
    for pcs,col in sol:
        for r,c in pcs: out[r][c]=col
    return out

